export type Item = {
  type: string;
  material: string;
  enchantment: number;
  cursed: boolean;
};

export type Step = {
  op: string;
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type StepResult = {
  premium: number;
};

export type ScenarioResult = {
  results: StepResult[];
};

const BASE_PRICES: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

// Expressed as integer percent rather than a 1.1 factor: floating-point
// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
// while scaling by 110 and dividing by 100 stays exact for these prices.
const FIRST_CONTRACT_PERCENT = 110;
const PERCENT = 100;
const CONTRACT_FEE = 5;

const basePriceOf = (item: Item): number => BASE_PRICES[item.type];

const applyPercent = (amount: number, percent: number): number =>
  (amount * percent) / PERCENT;

const quote = (step: Step): StepResult => ({
  premium:
    applyPercent(basePriceOf(step.items[0]), FIRST_CONTRACT_PERCENT) +
    CONTRACT_FEE,
});

export const run = (scenario: Scenario): ScenarioResult => ({
  results: [quote(scenario.steps[0])],
});

