import { describe, it, expect } from "vitest";
import { run } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quoting: base price list (new customer, first contract: +10 %, +5 G fee) ---
  it("quotes a sword for a brand-new customer — 100 * 1.1 + 5 = 115 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes an amulet for a brand-new customer — 60 * 1.1 + 5 = 71 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("quotes a staff for a brand-new customer — 80 * 1.1 + 5 = 93 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "staff", material: "oak", enchantment: 1, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it("quotes a potion for a brand-new customer — 40 * 1.1 + 5 = 49 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "potion", material: "glass", enchantment: 0, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 49 }] });
  });
  it("quotes a single rune component — 25 * 1.1 + 5 = 33 G (rounded up from 32.5)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune", material: "stone", enchantment: 1, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 33 }] });
  });
  it("quotes a single moonstone component — 25 * 1.1 + 5 = 33 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "moonstone", material: "stone", enchantment: 0, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 33 }] });
  });
  it("sums base premiums of several main items — sword + potion = 140 * 1.1 + 5 = 159 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 1, cursed: false },
            { type: "potion", material: "glass", enchantment: 0, cursed: false },
          ],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 159 }] });
  });

  // --- Quoting: component building blocks ---
  it("charges 60 G for a building block of 3 alike components instead of 75 G — 60 * 1.1 + 5 = 71 G", () => {
    const rune = {
      type: "rune",
      material: "stone",
      enchantment: 1,
      cursed: false,
    };
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [rune, rune, rune] }],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("charges block price plus single price for 4 alike components — (60 + 25) * 1.1 + 5 = 98.5 -> 99 G", () => {
    const rune = {
      type: "rune",
      material: "stone",
      enchantment: 1,
      cursed: false,
    };
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [rune, rune, rune, rune] }],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 99 }] });
  });
  it("charges two block prices for 6 alike components — 120 * 1.1 + 5 = 137 G", () => {
    const moonstone = {
      type: "moonstone",
      material: "stone",
      enchantment: 0,
      cursed: false,
    };
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [moonstone, moonstone, moonstone, moonstone, moonstone, moonstone],
        },
      ],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 137 }] });
  });
  it("does not form a block from unlike components — 2 runes + 1 moonstone = 75 * 1.1 + 5 = 87.5 -> 88 G", () => {
    const rune = {
      type: "rune",
      material: "stone",
      enchantment: 1,
      cursed: false,
    };
    const moonstone = {
      type: "moonstone",
      material: "stone",
      enchantment: 0,
      cursed: false,
    };
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [rune, rune, moonstone] }],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 88 }] });
  });

  it("does not form a building block from main items — 3 swords = 300 * 1.1 + 5 = 335 G", () => {
    const sword = {
      type: "sword",
      material: "steel",
      enchantment: 1,
      cursed: false,
    };
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [sword, sword, sword] }],
    };

    expect(run(scenario)).toEqual({ results: [{ premium: 335 }] });
  });

  // --- Quoting: risk surcharges ---
  it.todo("adds a 50 % risk surcharge for a cursed item — 100 * 1.5 * 1.1 + 5 = 170 G");
  it.todo("adds a 30 % risk surcharge for enchantment level 5 — 100 * 1.3 * 1.1 + 5 = 148 G");
  it.todo("adds no enchantment surcharge below level 5 — enchantment 4 sword = 115 G");
  it.todo("stacks the cursed and high-enchantment surcharges on the same item — 100 * 1.5 * 1.3 * 1.1 + 5 = 219.5 -> 220 G");
  it.todo("applies surcharges per item, not to the whole quote — cursed sword + plain potion = (150 + 40) * 1.1 + 5 = 214 G");

  // --- Quoting: customer modifiers ---
  it.todo("grants a 20 % loyalty discount at 2 years with MHPCO — 100 * 1.1 * 0.8 + 5 = 93 G");
  it.todo("grants no loyalty discount below 2 years with MHPCO — 1 year sword = 115 G");
  it.todo("applies a 15 % discount to the second contract instead of the 10 % first-insurance surcharge — 100 * 0.85 + 5 = 90 G");
  it.todo("applies the 15 % discount to every contract after the first — third contract sword = 90 G");
  it.todo("combines the loyalty discount with the repeat-contract discount — 100 * 0.8 * 0.85 + 5 = 73 G");

  // --- Claims: basics ---
  it.todo("pays a damage minus the 100 G deductible — 200 G damage to an amulet pays 100 G");
  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
  it.todo("never pays a negative amount — 40 G damage pays 0 G");
  it.todo("applies one deductible per incident, not per damaged item — two 200 G damages pay 300 G");
  it.todo("reports the remaining cap after a claim — amulet policy cap 1200, 100 G payout leaves 1100 G");

  // --- Claims: reimbursement rates ---
  it.todo("reimburses damage to an item with enchantment level 8 at 50 % — 500 G damage pays 250 - 100 = 150 G");
  it.todo("reimburses damage to an item with enchantment level 7 in full — 500 G damage pays 400 G");
  it.todo("reimburses damage to a dragon-material item in full even at enchantment 8 — 500 G damage pays 400 G");
  it.todo("applies the rate per damaged item before the single deductible is subtracted");

  // --- Claims: cap ---
  it.todo("caps the total payout at twice the insurance sum — amulet policy pays at most 1200 G overall");
  it.todo("accumulates payouts across claims against the same policy and reduces the cap each time");
  it.todo("pays 0 G once the cap is exhausted and reports a remaining cap of 0 G");
  it.todo("keeps caps of separate policies independent");

  // --- Multi-step scenarios ---
  it.todo("processes a quote followed by two claims on the same policy (schema example 2)");
  it.todo("returns one result per step, in step order, with the fields matching each operation");
});

