// because every step so far is a quote step. Once claim steps exist this
// must become a running count of quote steps only.
export const run = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, stepIndex) =>
    step.op === "claim"
      ? claim(step, policyAt(scenario.steps, step.policy))
