  const scenario: Scenario = {
    customer: { yearsWithMHPCO: 5 },
    steps: [
      {
        op: "quote",
        items: [
          { type: "sword", material: "steel", enchantment: 8, cursed: false },
          { type: "amulet", material: "silver", enchantment: 2, cursed: false },
