      },
      {
        op: "claim",
        policy: 0,
        incident: {
          cause: "avalanche",
          damages: [
            { itemType: "sword", amount: 400 },
            { itemType: "amulet", amount: 200 },
          ],
        },
      },
    ],
  };

  expect(run(scenario)).toEqual({
    results: [{ premium: 173 }, { payout: 300, remainingCap: 2900 }],
  });
});

